/**
 * Temporary coverage for the archived-project freeze. Deleted after the run.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as attachmentService from "@/server/services/attachment-service";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Issue } from "@/types/issue";

const PAST = "2026-01-01T00:00:00.000Z";
const NOW = new Date("2026-06-01T07:00:00.000Z");

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  resetOverdueTracking();
});

afterAll(() => {
  cleanup();
});

async function archivedTenant(slug: string): Promise<{ tenant: Tenant; issue: Issue }> {
  const tenant = await createTenant(slug, "growth");
  const issue = await issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, tenant.project.id, {
      title: `Live issue ${slug}`,
      dueAt: PAST,
      assigneeId: tenant.userIds.member,
    }),
  );
  await projectService.archiveProject(tenant.actors.admin, {
    orgId: tenant.org.id,
    projectId: tenant.project.id,
    archiveIssues: false,
  });
  return { tenant, issue };
}

describe("archived project freeze", () => {
  it("rejects issue writes, keeps the row, and publishes nothing", async () => {
    const { tenant, issue } = await archivedTenant("freeze-issue");
    const before = await issueRepo.findIssueById(tenant.org.id, issue.id);
    const events: string[] = [];
    const off = subscribe("issue.updated", () => events.push("updated"));
    const offStatus = subscribe("issue.status_changed", () => events.push("status"));
    const offAssigned = subscribe("issue.assigned", () => events.push("assigned"));
    const offArchived = subscribe("issue.archived", () => events.push("archived"));

    try {
      await expect(
        issueService.updateIssue(tenant.actors.member, {
          orgId: tenant.org.id,
          issueId: issue.id,
          title: "rewritten",
        }),
      ).rejects.toMatchObject({ name: "AlreadyArchivedError", entity: "Project", id: tenant.project.id });

      await expect(
        issueService.changeIssueStatus(tenant.actors.member, {
          orgId: tenant.org.id,
          issueId: issue.id,
          status: "in_progress",
        }),
      ).rejects.toBeInstanceOf(AlreadyArchivedError);

      await expect(
        issueService.moveIssue(tenant.actors.member, {
          orgId: tenant.org.id,
          issueId: issue.id,
          toStatus: "todo",
          toIndex: 0,
        }),
      ).rejects.toBeInstanceOf(AlreadyArchivedError);

      await expect(
        issueService.assignIssue(tenant.actors.member, {
          orgId: tenant.org.id,
          issueId: issue.id,
          assigneeId: tenant.userIds.admin,
        }),
      ).rejects.toBeInstanceOf(AlreadyArchivedError);

      await expect(
        issueService.assignIssue(tenant.actors.member, {
          orgId: tenant.org.id,
          issueId: issue.id,
          assigneeId: null,
        }),
      ).rejects.toBeInstanceOf(AlreadyArchivedError);

      await expect(
        issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id),
      ).rejects.toBeInstanceOf(AlreadyArchivedError);

      await expect(
        issueService.updateIssue(tenant.actors.viewer, {
          orgId: tenant.org.id,
          issueId: issue.id,
          title: "nope",
        }),
      ).rejects.toBeInstanceOf(PermissionDeniedError);
    } finally {
      off();
      offStatus();
      offAssigned();
      offArchived();
    }

    expect(events).toEqual([]);
    const after = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(after).toEqual(before);

    const read = await issueService.getIssue(tenant.actors.viewer, tenant.org.id, issue.id);
    expect(read.issue.id).toBe(issue.id);
    const board = await issueService.getBoard(tenant.actors.viewer, tenant.org.id, tenant.project.id);
    expect(board.flatMap((column) => column.issues.map((row) => row.id))).toContain(issue.id);
    const listed = await issueService.listIssues(tenant.actors.viewer, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      limit: 25,
      cursor: null,
    });
    expect(listed.items.map((row) => row.id)).toContain(issue.id);
  });

  it("still reports an archived issue as the issue when the project is archived too", async () => {
    const tenant = await createTenant("freeze-both", "growth");
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Will be archived" }),
    );
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: true,
    });

    await expect(
      issueService.updateIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        title: "still the issue",
      }),
    ).rejects.toMatchObject({ entity: "Issue", id: issue.id });
  });

  it("rejects comment and attachment writes and keeps reads", async () => {
    const tenant = await createTenant("freeze-sub", "growth");
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "With extras" }),
    );
    const comment = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "original",
      parentId: null,
      mentionedUserIds: [],
    });
    const attachment = await attachmentService.addAttachment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      filename: "notes.txt",
      contentType: "text/plain",
      sizeBytes: 12,
    });

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: false,
    });

    const events: string[] = [];
    const offCreated = subscribe("comment.created", () => events.push("created"));
    const offDeleted = subscribe("comment.deleted", () => events.push("deleted"));

    try {
      await expect(
        commentService.createComment(tenant.actors.member, {
          orgId: tenant.org.id,
          issueId: issue.id,
          body: "nope",
          parentId: null,
          mentionedUserIds: [],
        }),
      ).rejects.toMatchObject({ entity: "Project" });

      await expect(
        commentService.createComment(tenant.actors.viewer, {
          orgId: tenant.org.id,
          issueId: issue.id,
          body: "viewer",
          parentId: null,
